// Keeps only emails that look like they are about a job application,
// and cleans them up so the LLM gets short, plain text.

// Emails from these applicant-tracking systems always pass.
const ATS_DOMAINS = [
  'greenhouse.io','greenhouse-mail.io','lever.co','myworkdayjobs.com','myworkday.com','workday.com',
  'ashbyhq.com','smartrecruiters.com','icims.com','taleo.net','oraclecloud.com','successfactors.com',
  'successfactors.eu','workable.com','jobvite.com','bamboohr.com','recruitee.com','teamtailor.com',
  'teamtailor-mail.com','personio.de','personio.com','breezy.hr','jazzhr.com','applytojob.com',
  'rippling.com','dover.com','pinpointhq.com','comeet.co','hirehive.com','zohorecruit.com',
];
// Job boards send lots of noise, so these only pass when the text also has job keywords.
const BOARD_DOMAINS = ['linkedin.com','indeed.com','indeedemail.com','glassdoor.com','ziprecruiter.com','wellfound.com','otta.com','monster.com'];

const KEYWORDS = /(your application|application (received|submitted|status|update|for)|thank(s| you) for (applying|your (interest|application))|applied (for|to)|we('ve| have) received your|candidacy|candidate|interview|assessment|coding (challenge|test)|take[- ]home|hiring (team|manager)|recruit(er|ing|ment)|talent acquisition|next steps|unfortunately|move forward|moving forward|other candidates|job offer|offer letter|shortlisted|phone screen)/i;
const NOISE = /(job alert|jobs? (for|matching) you|new jobs|recommended (jobs|for you)|is hiring|are hiring|people (viewed|are looking)|viewed your profile|weekly digest|newsletter|webinar|invitation to connect|endorsed you|your network)/i;

function baseDomain(addr) {
  const d = (addr.split('@')[1] || '').toLowerCase().trim();
  const parts = d.split('.');
  if (parts.length > 2 && ['co','com','org','net','ac','gov','edu'].includes(parts[parts.length - 2])) {
    return parts.slice(-3).join('.');
  }
  return parts.slice(-2).join('.');
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&#39;|&rsquo;/g, "'").replace(/&quot;/g, '"');
}

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const fromObj = (m.from && m.from.value && m.from.value[0]) || {};
  const fromAddress = (fromObj.address || m.From || '').toLowerCase();
  const fromName = fromObj.name || '';
  const subject = m.subject || m.Subject || '';
  const fromDomain = baseDomain(fromAddress);

  let body = m.text || stripHtml(m.html || m.textAsHtml || m.snippet || '');
  body = body
    .replace(/https?:\/\/\S+/g, '[link]')
    .replace(/[{}]/g, '')          // braces confuse the LLM prompt template
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n+/g, '\n')
    .trim()
    .slice(0, 3500);

  const haystack = subject + '\n' + body.slice(0, 1500);
  const isAts = ATS_DOMAINS.some(d => fromAddress.endsWith(d));
  const isBoard = BOARD_DOMAINS.some(d => fromAddress.endsWith(d));
  const hasKeywords = KEYWORDS.test(haystack);
  const isNoise = NOISE.test(subject);

  const keep = !isNoise && (isAts || hasKeywords);
  if (!keep) continue;
  if (isBoard && !hasKeywords) continue;

  out.push({
    json: {
      messageId: m.id,
      threadId: m.threadId,
      fromAddress,
      fromName,
      fromDomain,
      viaAts: isAts,
      viaBoard: isBoard,
      subject: subject.replace(/[{}]/g, ''),
      date: m.date ? new Date(m.date).toISOString() : new Date().toISOString(),
      body,
    },
  });
}
return out;

// Builds the list of known applications from Notion, tries a cheap exact
// match first, then writes the prompt for the LLM.
const email = $('Loop Over Emails').first().json;
const results = $input.first().json.results || [];

const txt = p => !p ? '' : (p.title || p.rich_text || []).map(t => t.plain_text).join('').trim();
const clean = s => String(s || '').replace(/[{}]/g, '').replace(/\s+/g, ' ').trim();

const candidates = results.map(pg => {
  const p = pg.properties || {};
  return {
    id: pg.id,
    url: pg.url,
    company: txt(p['Company']),
    role: txt(p['Role']),
    domain: txt(p['Company Domain']).toLowerCase().replace(/^www\./, ''),
    threadIds: txt(p['Thread IDs']).split(/[\s,]+/).filter(Boolean),
    status: (p['Status'] && p['Status'].select && p['Status'].select.name) || 'Applied',
    lastReplySummary: txt(p['Last Reply Summary']),
  };
});

// 1) Same Gmail thread as a known application = certain match.
let detIndex = candidates.findIndex(c => c.threadIds.includes(email.threadId));
let detReason = detIndex >= 0 ? 'thread' : '';
// 2) Sender's domain equals the company's domain (not for ATS / job-board senders).
if (detIndex < 0 && !email.viaAts && !email.viaBoard && email.fromDomain) {
  const hits = candidates
    .map((c, i) => ({ c, i }))
    .filter(x => x.c.domain && (x.c.domain === email.fromDomain || x.c.domain.endsWith('.' + email.fromDomain) || email.fromDomain.endsWith('.' + x.c.domain)));
  if (hits.length === 1) { detIndex = hits[0].i; detReason = 'domain'; }
}

const shown = candidates.slice(0, 60);
const list = shown.length
  ? shown.map((c, i) => `${i + 1}. ${clean(c.company)} | ${clean(c.role) || 'role unknown'} | ${c.domain || 'no domain'} | status: ${c.status}`).join('\n')
  : '(none yet)';

const prompt = `You triage a job seeker's inbox. Read the EMAIL and classify it.

EMAIL TYPES (pick exactly one):
- application_confirmation: automatic "we received your application" or "thank you for applying"
- rejection: the company is not moving forward with the candidate
- interview_invite: invitation to schedule or attend an interview, phone screen or call
- assessment: coding test, take-home task, online assessment or questionnaire to complete
- offer: a job offer
- info_request: the company asks for documents, availability, references or answers
- status_update: any other update on an application (still reviewing, application viewed, position on hold)
- recruiter_outreach: a recruiter reaching out about a NEW role the candidate did not apply to
- other: not about a specific job application (job alerts, newsletters, marketing, social notifications)

KNOWN APPLICATIONS (numbered):
${list}

Return ONLY a JSON object with exactly these keys:
"email_type": one of the types above
"company": the hiring company (the employer, NOT the job board or ATS such as LinkedIn, Indeed, Greenhouse, Workday, Lever), or ""
"role": the job title, or ""
"matched_application": the number of the KNOWN APPLICATION this email is about, or null if none clearly matches
"summary": one or two short sentences saying what the email says
"next_action": what the candidate should do next, or ""
"deadline": any date or time given for the next step, as written in the email, or ""

EMAIL
From: ${clean(email.fromName)} <${email.fromAddress}>
Subject: ${clean(email.subject)}
Date: ${email.date}
Body:
${email.body}`;

return [{ json: { prompt, candidates, detIndex, detReason, shownCount: shown.length } }];

// Parses the LLM answer, picks the matching application, applies the
// status rules and builds the Notion request + routing for the Switch.
const email = $('Loop Over Emails').first().json;
const prep = $('Prepare LLM Input').first().json;
const cfg = $('Config').first().json;

// ---- parse LLM output (handles "thinking" models that write notes before the JSON)
let raw = $json.text ?? $json.output ?? $json.response ?? '';
let r = null;
if (raw && typeof raw === 'object') r = raw;
else {
  const str = String(raw).replace(/<think>[\s\S]*?<\/think>/gi, '');
  const found = [];
  for (let i = 0; i < str.length; i++) {
    if (str[i] !== '{') continue;
    let depth = 0, inStr = false, esc = false;
    for (let j = i; j < str.length; j++) {
      const ch = str[j];
      if (inStr) {
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === '"') inStr = false;
        continue;
      }
      if (ch === '"') inStr = true;
      else if (ch === '{') depth++;
      else if (ch === '}') { depth--; if (depth === 0) { found.push(str.slice(i, j + 1)); break; } }
    }
  }
  for (const c of found.reverse()) {
    try { const o = JSON.parse(c); if (o && o.email_type) { r = o; break; } } catch (e) {}
  }
}
if (!r || $json.error || !r.email_type) {
  // Route 4 = don't label, retry next run (emails drop out of the 2-day window on their own).
  return [{ json: { route: 4, action: 'retry', messageId: email.messageId, reason: $json.error || 'LLM output not parseable', raw: String(raw).slice(0, 500) } }];
}

const TYPES = ['application_confirmation','rejection','interview_invite','assessment','offer','info_request','status_update','recruiter_outreach','other'];
const type = TYPES.includes(r.email_type) ? r.email_type : 'other';
const s = v => (v === null || v === undefined) ? '' : String(v).trim();
const company = s(r.company);
const role = s(r.role);
const summary = s(r.summary);
const nextAction = s(r.next_action);
const deadline = s(r.deadline);

// ---- find the matching application
const cands = prep.candidates || [];
let match = null, matchedBy = '';
if (prep.detIndex >= 0) { match = cands[prep.detIndex]; matchedBy = prep.detReason; }
if (!match) {
  const n = parseInt(r.matched_application, 10);
  if (n >= 1 && n <= prep.shownCount) { match = cands[n - 1]; matchedBy = 'llm'; }
}
if (!match && company) {
  const norm = x => s(x).toLowerCase().replace(/\b(inc|ltd|llc|gmbh|plc|corp|corporation|co|limited|group|technologies|technology|labs)\b/g, '').replace(/[^a-z0-9]/g, '');
  const c = norm(company);
  if (c.length >= 3) {
    const hits = cands.filter(x => { const k = norm(x.company); return k && (k === c || (k.length >= 4 && (k.includes(c) || c.includes(k)))); });
    if (hits.length === 1) { match = hits[0]; matchedBy = 'name'; }
  }
}

// ---- status rules
const TYPE_STATUS = {
  application_confirmation: 'Applied', status_update: 'Under Review', info_request: 'Under Review',
  assessment: 'Assessment', interview_invite: 'Interview', offer: 'Offer', rejection: 'Rejected',
};
const RANK = { 'No Response': 0, 'Applied': 1, 'Under Review': 2, 'Assessment': 3, 'Interview': 4, 'Offer': 5, 'Rejected': 5 };
const mapped = TYPE_STATUS[type];
let status = mapped;
if (match && mapped) {
  const cur = match.status || 'Applied';
  const terminal = mapped === 'Rejected' || mapped === 'Offer';
  status = (terminal || (RANK[mapped] ?? 0) > (RANK[cur] ?? 0)) ? mapped : cur;
}

// ---- helpers for Notion properties
const rt = v => ({ rich_text: v ? [{ text: { content: s(v).slice(0, 1900) } }] : [] });
const day = email.date.slice(0, 10);
const goodDomain = (!email.viaAts && !email.viaBoard && email.fromDomain && !/^(gmail|googlemail|outlook|hotmail|yahoo|icloud|proton|protonmail)\./.test(email.fromDomain)) ? email.fromDomain : '';
const source = /linkedin/.test(email.fromAddress) ? 'LinkedIn' : /indeed/.test(email.fromAddress) ? 'Indeed' : (email.viaBoard ? 'Other' : 'Company Site');
const isReply = ['rejection','interview_invite','assessment','offer','info_request','status_update'].includes(type);
const replyText = [summary, deadline ? `Deadline: ${deadline}` : ''].filter(Boolean).join(' ');

let route = 3, action = 'skip', notify = false, pageId = null, pageUrl = match ? match.url : '', notionBody = null;

if (type === 'other') {
  route = 3; action = 'skip';
} else if (type === 'recruiter_outreach') {
  route = 2; action = 'notify'; notify = true;
} else if (match) {
  // update existing row
  const props = { 'Status': { select: { name: status } } };
  const threads = match.threadIds.includes(email.threadId) ? match.threadIds : [...match.threadIds, email.threadId];
  props['Thread IDs'] = rt(threads.join(', '));
  if (!match.role && role) props['Role'] = rt(role);
  if (!match.domain && goodDomain) props['Company Domain'] = rt(goodDomain);
  if (isReply) {
    props['Last Reply Date'] = { date: { start: day } };
    props['Last Reply Summary'] = rt(replyText);
    props['Next Action'] = rt(nextAction);
  }
  notionBody = { properties: props };
  pageId = match.id;
  route = 1; action = 'update';
  notify = isReply; // a second confirmation email for a known job is not worth a ping
} else if (type === 'application_confirmation' || isReply) {
  // create new row
  const props = {
    'Company': { title: [{ text: { content: (company || email.fromName || email.fromDomain || 'Unknown company').slice(0, 200) } }] },
    'Role': rt(role),
    'Status': { select: { name: mapped } },
    'Source': { select: { name: source } },
    'Thread IDs': rt(email.threadId),
    'Needs Review': { checkbox: isReply }, // a reply for a job we never logged: double-check it
  };
  if (goodDomain) props['Company Domain'] = rt(goodDomain);
  if (type === 'application_confirmation') props['Applied Date'] = { date: { start: day } };
  if (isReply) {
    props['Last Reply Date'] = { date: { start: day } };
    props['Last Reply Summary'] = rt(replyText);
    props['Next Action'] = rt(nextAction);
  }
  notionBody = { parent: { database_id: cfg.notionDatabaseId }, properties: props };
  route = 0; action = 'create'; notify = true;
}

return [{ json: {
  route, action, notify, type, status: status || '', company: company || (match && match.company) || '',
  role: role || (match && match.role) || '', summary, nextAction, deadline, matchedBy,
  pageId, pageUrl, notionBody,
  messageId: email.messageId, threadId: email.threadId, subject: email.subject, fromAddress: email.fromAddress,
} }];

// Formats the Discord message.
const d = $('Decide').first().json;
const pageUrl = $json.url || d.pageUrl || '';
const gmailUrl = `https://mail.google.com/mail/u/0/#all/${d.threadId}`;

const STYLE = {
  application_confirmation: { emoji: '📝', label: 'Application logged', color: 3447003 },
  rejection:        { emoji: '❌', label: 'Rejection',          color: 15158332 },
  interview_invite: { emoji: '🎉', label: 'Interview invite',   color: 3066993 },
  assessment:       { emoji: '🧩', label: 'Assessment',         color: 15105570 },
  offer:            { emoji: '🏆', label: 'OFFER',              color: 15844367 },
  info_request:     { emoji: '📨', label: 'Info requested',     color: 3447003 },
  status_update:    { emoji: '🔄', label: 'Status update',      color: 9807270 },
  recruiter_outreach: { emoji: '👋', label: 'Recruiter outreach', color: 10181046 },
};
const st = STYLE[d.type] || { emoji: '📬', label: 'Update', color: 9807270 };
const links = [`[Open email](${gmailUrl})`, pageUrl ? `[Notion](${pageUrl})` : ''].filter(Boolean).join(' · ');

let body;
if (d.type === 'application_confirmation') {
  body = { content: `${st.emoji} Logged new application: **${d.role || 'role unknown'}** at **${d.company || 'unknown company'}** · ${links}` };
} else {
  const fields = [
    { name: 'Role', value: d.role, inline: true },
    { name: 'Status', value: d.status, inline: true },
    { name: 'Next action', value: d.nextAction, inline: false },
    { name: 'Deadline', value: d.deadline, inline: true },
    { name: 'Links', value: links, inline: false },
  ].filter(f => f.value).map(f => ({ ...f, value: String(f.value).slice(0, 1000) }));
  body = {
    embeds: [{
      title: `${st.emoji} ${st.label}: ${d.company || 'Unknown company'}`.slice(0, 250),
      description: (d.summary || '').slice(0, 2000),
      color: st.color,
      fields,
      footer: { text: `${d.fromAddress} · ${d.subject}`.slice(0, 2000) },
      timestamp: new Date().toISOString(),
    }],
  };
}
return [{ json: { discordBody: body } }];
